// FIX: Handle draft persistence across navigation and refresh
function handleDraftPersistence() {
  // Ensure draft exists in storage when app loads
  ensureDraftExists();

  // Setup draft persistence mechanism
  let currentDraft = readDraft();
  let lastSavedDraft = JSON.stringify(currentDraft);
  let isTyping = false;
  let typingTimer = null;

  // Track draft changes and save to localStorage
  function saveDraftToStorage() {
    const draft = { title: title.value, body: body.value };
    writeDraft(draft);
    lastSavedDraft = JSON.stringify(draft);
  }

  // Setup input listeners when editor is active
  function setupEditorListeners() {
    if (screen === 'editor') {
      const title = app.querySelector('[data-testid="note-title"]');
      const body = app.querySelector('[data-testid="note-body"]');

      title.oninput = function() {
        isTyping = true;
        clearTimeout(typingTimer);
        typingTimer = setTimeout(saveDraftToStorage, 100); // Debounce saves
      };

      body.oninput = function() {
        isTyping = true;
        clearTimeout(typingTimer);
        typingTimer = setTimeout(saveDraftToStorage, 100); // Debounce saves
      };
    }
  }

  // Handle screen transitions to preserve draft
  function handleScreenChange(newScreen) {
    if (newScreen === 'editor' && screen !== 'editor') {
      // Switching to editor: restore draft
      currentDraft = readDraft();
      const title = app.querySelector('[data-testid="note-title"]');
      const body = app.querySelector('[data-testid="note-body"]');
      if (title && body) {
        title.value = currentDraft.title;
        body.value = currentDraft.body;
        // Force character count update
        app.querySelector('#character-count').textContent = `${currentDraft.body.length} characters`;
      }
    }

    screen = newScreen;
    render();
  }

  // Override screen change handlers to use our method
  const originalEditorTab = app.querySelector('[data-testid="editor-tab"]');
  const originalNotesTab = app.querySelector('[data-testid="notes-tab"]');
  const originalBackupTab = app.querySelector('[data-testid="backup-tab"]');

  if (originalEditorTab) {
    originalEditorTab.onclick = () => handleScreenChange('editor');
  }
  if (originalNotesTab) {
    originalNotesTab.onclick = () => handleScreenChange('notes');
  }
  if (originalBackupTab) {
    originalBackupTab.onclick = () => handleScreenChange('backup');
  }

  // Setup initial listeners
  setupEditorListeners();
}

